output_text:
[
  {
    "id": "no_cart_in_single_file_aisle",
    "text": "A shopper must not have a cart inside a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "A shopper must not move into a single-file shelf aisle while pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "cartEntryToSingleFile": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartEntryToSingleFile"
    }
  },
  {
    "id": "park_before_north_canyon",
    "text": "At the mouth of a north-going single-file shelf canyon, a shopper must not go north while still holding the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "singleFileMouth",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "retrieve_cart_after_canyon",
    "text": "After entering a single-file shelf aisle without the cart, the shopper is obliged to regain the cart before exiting.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enterSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "enterSingleFileWithoutCart",
      "discharge": "hasCart"
    }
  },
  {
    "id": "no_cartless_ordinary_movement",
    "text": "Except for the initial step and cartless movement in or at a single-file shelf aisle, ordinary movement should be done with the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "initialEntranceCell": "at(0,7)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "singleFileShelfAisle"
          },
          {
            "not": "singleFileMouth"
          },
          {
            "not": "initialEntranceCell"
          }
        ]
      }
    }
  },
  {
    "id": "drop_cart_only_at_wide_mouth",
    "text": "A shopper may abandon or park the cart only at a wide aisle mouth used for entering a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            3
          ]
        },
        "singleFileMouth": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "legalCartParkingMouth": {
          "and": [
            "wideAisle",
            "singleFileMouth"
          ]
        }
      },
      "events": {
        "dropCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "dropCart",
          {
            "not": "legalCartParkingMouth"
          }
        ]
      }
    }
  },
  {
    "id": "open_shelf_picks_need_cart",
    "text": "When interacting with a shelf from an ordinary non-single-file aisle, the shopper should have the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "ordinaryShelfApproach": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "ordinaryShelfApproach",
          "INTERACT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_between_facing_shelves",
    "text": "A shopper must not take a cart into a narrow aisle flanked by shelves on both sides.",
    "abstraction": {
      "state_properties": {
        "betweenFacingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "narrowBetweenFacingShelves": {
          "and": [
            "betweenFacingShelves",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "narrowBetweenFacingShelves"
        ]
      }
    }
  }
]
